/// Checkpoint API: get by id and search by branch/commit message (paginated)
@RestController
@RequiredArgsConstructor
@Slf4j
@RequestMapping("/api/v1/admin/checkpoint")
@Tag(name = "Checkpoint", description = "Checkpoint get and search APIs")
public class CheckpointController {

    private final CheckpointService checkpointService;
    private final CheckpointSyncService checkpointSyncService;

    /// Get single checkpoint by ID
    @GetMapping("/get")
    @Operation(summary = "Get checkpoint", description = "Get full checkpoint details by ID")
    public CheckpointDTO get(@ModelAttribute @Valid IdPayload payload) {
        return checkpointService.get(payload.getId());
    }

    /// Get distinct repos for filter dropdown (by time range and optional filters)
    @GetMapping("/repos")
    @Operation(summary = "Get repos for filter", description = "Returns distinct repos from checkpoints matching the filter (startTime, endTime required)")
    public List<RepoOptionDTO> getRepos(@ModelAttribute @Valid CheckpointFilterParams params) {
        return checkpointService.getReposForFilter(params);
    }

    /// Get distinct commit authors for filter dropdown
    @GetMapping("/commit-authors")
    @Operation(summary = "Get commit authors for filter", description = "Returns distinct commit author names from checkpoints matching the filter")
    public List<String> getCommitAuthors(@ModelAttribute @Valid CheckpointFilterParams params) {
        return checkpointService.getCommitAuthorsForFilter(params);
    }

    /// Search checkpoints by repoIds, commitAuthorNames, branch, commit message, time range (paginated)
    @GetMapping("/search")
    @Operation(summary = "Search checkpoints", description = "Search checkpoints by repoIds, commitAuthorNames, branch, commit message (fuzzy), startTime/endTime, paginated")
    public PagerPayload<CheckpointDTO> search(
            @ModelAttribute @Valid CheckpointSearchParams params,
            @Parameter(description = "Pagination: page (0-based), size, sort (e.g. commitTime,desc)")
            @PageableDefault(sort = {"commitTime"}, size = 20, direction = Sort.Direction.DESC) Pageable pageable) {
        Page<CheckpointDTO> page = checkpointService.search(params, pageable);
        return new PagerPayload<>(page, pageable);
    }

    /// Trigger checkpoint sync for one repo (incremental unless fullScan=true)
    @PostMapping("/sync/repo/{repoId}")
    @Operation(summary = "Sync repo checkpoints", description = "Immediately sync checkpoints for the given repo. Use fullScan=true to walk all commits.")
    public void syncRepo(
            @PathVariable Long repoId,
            @RequestParam(required = false, defaultValue = "false") boolean fullScan) {
        checkpointSyncService.syncRepo(repoId, fullScan);
    }

    /// Trigger checkpoint sync for all repos
    @PostMapping("/sync/all")
    @Operation(summary = "Sync all checkpoints", description = "Immediately sync checkpoints for all repos. Use fullScan=true to full-scan each repo.")
    public void syncAll(@RequestParam(required = false, defaultValue = "false") boolean fullScan) {
        checkpointSyncService.syncAllRepos(fullScan);
    }
}
        checkpointMapper.updateEntity(params, entity);
        Checkpoint saved = checkpointRepository.save(entity);
        log.info("Updated checkpoint successfully, ID: {}, checkpointId: {}", saved.getId(), saved.getCheckpointId());
        CheckpointDTO dto = checkpointMapper.toDTO(saved);
        enrichCommitUrl(dto);
        return dto;
    }

    @Override
    public CheckpointDTO get(Long id) {
        Checkpoint entity = checkpointRepository.findById(id)
                .orElseThrow(() -> Errors.NOT_FOUND.toException("Checkpoint not found, ID: " + id));
        CheckpointDTO dto = checkpointMapper.toDTO(entity);
        enrichCommitUrl(dto);
        return dto;
    }

    @Override
    public void delete(Long id) {
        if (!checkpointRepository.existsById(id)) {
            throw Errors.INTERNAL_ERROR.toException("Checkpoint not found, ID: " + id);
        }
        checkpointRepository.deleteById(id);
        log.info("Deleted checkpoint successfully, ID: {}", id);
    }

    @Override
    public Page<CheckpointDTO> search(CheckpointSearchParams params, Pageable pageable) {
        QCheckpoint q = QCheckpoint.checkpoint;
        BooleanBuilder b = new BooleanBuilder();
        if (params.getRepoIds() != null && !params.getRepoIds().isEmpty()) {
            b.and(q.repoId.in(params.getRepoIds()));
        }
        if (params.getCommitAuthorNames() != null && !params.getCommitAuthorNames().isEmpty()) {
            b.and(q.commitAuthorName.in(params.getCommitAuthorNames()));
        }
        if (StrUtil.isNotBlank(params.getBranch())) {
            b.and(q.branch.containsIgnoreCase(params.getBranch()));
        }
        if (StrUtil.isNotBlank(params.getCommitMessage())) {
            b.and(q.commitMessage.containsIgnoreCase(params.getCommitMessage()));
        }
        if (params.getStartTime() != null) {
            b.and(q.commitTime.goe(params.getStartTime()));
        }
        if (params.getEndTime() != null) {
            b.and(q.commitTime.loe(params.getEndTime()));
        }
        var page = checkpointRepository.findAll(b, pageable);
        var rows = checkpointMapper.toRows(page.toList());
        enrichCommitUrls(rows);
        return new PageImpl<>(rows, pageable, page.getTotalElements());
    }

    private void enrichCommitUrl(CheckpointDTO dto) {
        if (dto.getRepoId() == null || StrUtil.isBlank(dto.getCommitSha())) {
            return;
        }
        repoRepository.findById(dto.getRepoId()).ifPresent(repo -> {
            GitPlatformAdapter adapter = platformAdapters.get(repo.getPlatform());
            if (adapter != null) {
                String url = adapter.buildCommitUrl(repo.getWebUrl(), dto.getCommitSha());
                if (url != null) {
                    dto.setCommitUrl(url);
                }
            }
        });
    }

    private void enrichCommitUrls(List<CheckpointDTO> dtos) {
        Set<Long> repoIds = dtos.stream()
                .map(CheckpointDTO::getRepoId)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());
        if (repoIds.isEmpty()) {
            return;
        }
        Map<Long, Repo> repoMap = repoRepository.findAllById(repoIds).stream()
                .collect(Collectors.toMap(Repo::getId, r -> r));
        for (CheckpointDTO dto : dtos) {
            if (dto.getRepoId() != null && StrUtil.isNotBlank(dto.getCommitSha())) {
                Repo repo = repoMap.get(dto.getRepoId());
                if (repo != null) {
                    GitPlatformAdapter adapter = platformAdapters.get(repo.getPlatform());
                    if (adapter != null) {
                        String url = adapter.buildCommitUrl(repo.getWebUrl(), dto.getCommitSha());
                        if (url != null) {
                            dto.setCommitUrl(url);
                        }
                    }
                }
            }
        }
    }

    @Override
    public List<RepoOptionDTO> getReposForFilter(CheckpointFilterParams params) {
        return filterRepository.findDistinctRepos(params);
    }

    @Override
    public List<String> getCommitAuthorsForFilter(CheckpointFilterParams params) {
        return filterRepository.findDistinctCommitAuthors(params);
    }
}

