 */
import type { CheckpointDTO } from '~/features/checkpoint/types/checkpoint.types'
import type { SessionDTO } from '~/features/checkpoint/types/session.types'

export interface FileEntry {
  path: string
  /** Number of AI sessions whose files_touched lists this path */
  sessionCount: number
  existsAtHead: boolean
}

export interface FileList {
  branches: string[]
  branch: string | null
  files: FileEntry[]
}

export interface FileSession {
  checkpoint: CheckpointDTO
  session: SessionDTO | null
  /** Session's files_touched lists the file */
  touchedFile: boolean
  /** Lines of the current version attributed to this session */
  currentLines: number
}

export interface FileLine {
  number: number
  content: string
  commitSha: string | null
  authorName: string | null
  commitTime: number
  /** Checkpoint.id (DB) of the commit that last changed the line, null if not an AI checkpoint commit */
  checkpointId: number | null
  /** Session.id (DB) the line is attributed to */
  sessionId: number | null
}

export interface FileHistory {
  path: string
  branch: string | null
  headSha: string | null
  existsAtHead: boolean
  binary: boolean
  truncated: boolean
  totalLines: number
  checkpointLines: number
  sessions: FileSession[]
  lines: FileLine[]
}
EOF
cat > features/file-history/api/file-history.api.ts <<'EOF'
/**
 * File history module - API client
 */
import { $adminApi } from '~/api/admin-api-client'
import type { PagerPayload } from '~/shared/types/api'
import type { RepoDTO } from '~/features/repository/types/repoDTO'
import type { FileHistory, FileList } from '../types/file-history.types'

export const fileHistoryApi = {
  /** All configured repositories (first 200) */
  async listRepos(): Promise<RepoDTO[]> {
    const res = await $adminApi<PagerPayload<RepoDTO>>('/repo/search', {
      method: 'GET',
      query: { page: 0, size: 200 },
    })
    return res.data ?? []
  },

  /** Files of a branch with AI session counts */
  listFiles(repoId: number, branch?: string | null): Promise<FileList> {
    return $adminApi<FileList>('/file/list', {
      method: 'GET',
      query: { repoId, ...(branch ? { branch } : {}) },
    })
  },

  /** Sessions that touched a file + line-by-line attribution */
  getHistory(repoId: number, path: string, branch?: string | null): Promise<FileHistory> {
    return $adminApi<FileHistory>('/file/history', {
      method: 'GET',
      query: { repoId, path, ...(branch ? { branch } : {}) },
    })
  },
}
EOF
cat > features/file-history/utils/session-colors.ts <<'EOF'
/**
 * Fixed-order categorical palette for sessions (validated for the white and slate-900 surfaces).
 * Slot order is never cycled: sessions beyond slot 8 share the neutral "other" color and rely on their label.
 */
const LIGHT = ['#2a78d6', '#eb6834', '#1baf7a', '#eda100', '#e87ba4', '#008300', '#6250d6', '#e34948']
const DARK = ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300', '#9085e9', '#e66767']
export const SESSION_SLOT_COUNT = LIGHT.length

/** CSS var name for a slot (0-based), or the "other" color when out of range */
export function sessionColorVar(slot: number | undefined): string {
  if (slot == null || slot < 0) return 'transparent'
  return slot < SESSION_SLOT_COUNT ? `var(--session-${slot + 1})` : 'var(--session-other)'
}

/** Inline style block declaring the palette for both color modes */
export const sessionPaletteCss = `
.file-history-root {
${LIGHT.map((c, i) => `  --session-${i + 1}: ${c};`).join('\n')}
  --session-other: #94a3b8;
}
.dark .file-history-root {
${DARK.map((c, i) => `  --session-${i + 1}: ${c};`).join('\n')}
  --session-other: #64748b;
}
`
EOF
